const PARTIAL='docs/superpowers/root-own/c2-notices-n3/b2-partial/';
const NATIVE='docs/superpowers/root-own/c2-notices-n3/native-models/';
const ROOT=process.cwd(),startedAt=new Date().toISOString(),env=process.env;
const sha256=value=>createHash('sha256').update(value).digest('hex');
const gitBlob=bytes=>createHash('sha1').update('blob '+bytes.length+'\0').update(bytes).digest('hex');
const requireFact=(value,label)=>{if(!value)throw Error('N3_OWN_MODELS_ADMISSION_REJECTED:'+label);};
const git=(...args)=>execFileSync('git',args,{cwd:ROOT,encoding:'utf8',maxBuffer:8*1024*1024}).trimEnd();
requireFact(process.version===NOMINATION.node,'node');
requireFact(env.GITHUB_ACTIONS==='true'&&env.GITHUB_EVENT_NAME==='push'&&env.GITHUB_RUN_ATTEMPT==='1','event-attempt');
requireFact(env.GITHUB_REPOSITORY===NOMINATION.repository&&env.GITHUB_REF==='refs/heads/'+NOMINATION.branch&&env.GITHUB_JOB===NOMINATION.job,'job-ref-repository');
requireFact(env.GITHUB_WORKFLOW_REF===NOMINATION.repository+'/'+NOMINATION.workflow+'@refs/heads/'+NOMINATION.branch,'workflow-ref');
requireFact(/^[1-9][0-9]*$/.test(env.GITHUB_RUN_ID??''),'run-id');
const head=git('rev-parse','HEAD'),tree=git('rev-parse','HEAD^{tree}');
requireFact(/^[a-f0-9]{40}$/.test(head)&&/^[a-f0-9]{40}$/.test(tree)&&env.GITHUB_SHA===head,'head');
requireFact(git('rev-list','--parents','-n','1','HEAD')===head+' '+NOMINATION.base&&git('rev-parse',NOMINATION.base+'^{tree}')===NOMINATION.baseTree,'base');
requireFact(git('show','-s','--format=%B','HEAD')===NOMINATION.message,'message');
function leaves(ref){
 const raw=execFileSync('git',['ls-tree','-r','-z','--full-tree',ref],{cwd:ROOT,encoding:'utf8',maxBuffer:8*1024*1024}),rows=raw.split('\0');requireFact(rows.pop()==='','tree-termination');
 const out=new Map();for(const row of rows){const m=/^([0-9]{6}) (blob|commit) ([a-f0-9]{40})\t(.+)$/.exec(row);requireFact(m&&!out.has(m[4]),'tree-row');out.set(m[4],{mode:m[1],type:m[2],blob:m[3]});}return out;
}
const baseLeaves=leaves(NOMINATION.base),headLeaves=leaves('HEAD');
requireFact(baseLeaves.size===3203,'base-leaf-count');
for(const [path,entry]of baseLeaves)requireFact(JSON.stringify(headLeaves.get(path))===JSON.stringify(entry),'original-preservation');
const added=[...headLeaves.keys()].filter(p=>!baseLeaves.has(p)).sort();
requireFact(JSON.stringify(added)===JSON.stringify(ADDITIONS)&&headLeaves.size===3248,'expanded-tree');
for(const path of ADDITIONS)requireFact(headLeaves.get(path)?.mode==='100644'&&headLeaves.get(path)?.type==='blob','addition-mode');
const loaded=new Map();
for(const entry of CLOSURE){
 const bytes=readFileSync(resolve(ROOT,entry.path));
 requireFact(bytes.length===entry.bytes&&sha256(bytes)===entry.sha256&&gitBlob(bytes)===entry.gitBlob&&headLeaves.get(entry.path)?.blob===entry.gitBlob,'closure:'+entry.path);
 loaded.set(entry.path,bytes);
}
const parse=path=>JSON.parse(loaded.get(path).toString('utf8'));
const selection=parse(NATIVE+'selection.json'),inputMap=parse(PARTIAL+'control-input-map.json');
requireFact(selection.schema==='afw.c2-notices-n3.own-models-selection.v1'&&selection.nomination===NOMINATION.message&&selection.ownModelsOnly===true&&selection.actualSourceExecution===false&&selection.finalSourceBinding===false,'selection-scope');
requireFact(selection.total===496&&selection.caseTimeoutMs===10000&&selection.ids.length===496&&new Set(selection.ids).size===496&&sha256(JSON.stringify(selection.ids))===selection.idsHash,'selection-ids');
requireFact(JSON.stringify(inputMap.data)===JSON.stringify(INPUT_MAP)&&Object.keys(INPUT_MAP).length===17,'input-map');
const data=Object.fromEntries(Object.entries(INPUT_MAP).map(([key,path])=>[key,parse(PARTIAL+path)]));
// Only immutable OWN modules may execute. All Source-intended material above remains JSON DATA.
const {n3B2AllControls}=await import(pathToFileURL(resolve(ROOT,PARTIAL+'controls.mjs')).href);
const suite=n3B2AllControls(data,sha256,inflateRawSync);
requireFact(suite&&Array.isArray(suite.checks)&&suite.checks.length===496,'executed-control-count');
const actualIds=suite.checks.map(row=>row.id);
requireFact(JSON.stringify(actualIds)===JSON.stringify(selection.ids)&&new Set(actualIds).size===496,'executed-id-order');
let passed=0,failed=0;
for(const row of suite.checks){
 requireFact(typeof row.pass==='boolean','executed-boolean');
 if(row.pass)passed++;else failed++;
 await test(row.id,{timeout:10000},()=>assert.equal(row.pass,true,'OWN control '+row.id));
}
requireFact(passed+failed===496,'executed-result-count');
