const selection=parse(NATIVE+'selection.json'),inputMap=parse(PARTIAL+'control-input-map.json');
requireFact(selection.schema==='afw.c2-notices-n3.own-models-selection.v1'&&selection.nomination===NOMINATION.message&&selection.ownModelsOnly===true&&selection.actualSourceExecution===false&&selection.finalSourceBinding===false,'selection-scope');
requireFact(selection.total===496&&selection.caseTimeoutMs===10000&&selection.ids.length===496&&new Set(selection.ids).size===496&&sha256(JSON.stringify(selection.ids))===selection.idsHash,'selection-ids');
requireFact(JSON.stringify(inputMap.data)===JSON.stringify(INPUT_MAP)&&Object.keys(INPUT_MAP).length===17,'input-map');
const data=Object.fromEntries(Object.entries(INPUT_MAP).map(([key,path])=>[key,parse(PARTIAL+path)]));
// Only immutable OWN modules may execute. All Source-intended material above remains JSON DATA.
const {n3B2AllControls}=await import(pathToFileURL(resolve(ROOT,PARTIAL+'controls.mjs')).href);
const suite=n3B2AllControls(data,sha256,inflateRawSync);
requireFact(suite&&Array.isArray(suite.checks)&&suite.checks.length===496,'executed-control-count');
const actualIds=suite.checks.map(row=>row.id);
requireFact(JSON.stringify(actualIds)===JSON.stringify(selection.ids)&&new Set(actualIds).size===496,'executed-id-order');
let passed=0,failed=0;
for(const row of suite.checks){
 requireFact(typeof row.pass==='boolean','executed-boolean');
 if(row.pass)passed++;else failed++;
 await test(row.id,{timeout:10000},()=>assert.equal(row.pass,true,'OWN control '+row.id));
}
requireFact(passed+failed===496,'executed-result-count');
const proof={
 schema:'afw.c2-notices-n3.own-models-proof.v1',nomination:NOMINATION.message,
 context:{repository:NOMINATION.repository,branch:NOMINATION.branch,workflow:NOMINATION.workflow,job:NOMINATION.job,baselineSource:NOMINATION.base,baselineTree:NOMINATION.baseTree,head,tree,runId:env.GITHUB_RUN_ID,runAttempt:1,node:process.version,startedAt,completedAt:new Date().toISOString()},
 bindings:{runnerHash:sha256(readFileSync(resolve(ROOT,NOMINATION.runner))),workflowHash:sha256(loaded.get(NOMINATION.workflow)),inputIndexHash:sha256(loaded.get(PARTIAL+'index.json')),closureHash:sha256(JSON.stringify(CLOSURE)),selectionHash:sha256(loaded.get(NATIVE+'selection.json')),proofSchemaHash:sha256(loaded.get(NATIVE+'proof.schema.json'))},
 selection:{count:actualIds.length,idsHash:sha256(JSON.stringify(actualIds))},
 results:{passed,failed,skipped:0,todo:0,cancelled:0,missing:0,extra:0,duplicate:0,ordered:true},
 models:{kind:'OWN_FICTITIOUS_INPUTS_AND_SOURCE_LITERAL_DATA_ONLY',inputFiles:17,ownModules:4},
 ownModelsExecuted:true,actualSourceExecution:false,finalSourceBinding:false,SourceQualified:false,Task1Pass:false,
 nonclaims:{historicalCauseProven:false,receiptAuthenticated:false,operationalReadiness:false,completePackage:false,PCoff:false,globalNativeDrainVerified:false,sdkNamespaceEmptyVerified:false}
};
const canonical=JSON.stringify(proof);
requireFact(Buffer.byteLength(canonical+'\n','utf8')<=24576,'proof-cap');
writeFileSync(resolve(ROOT,NOMINATION.proofFile),canonical+'\n',{encoding:'utf8',flag:'wx'});
process.stdout.write('AFW_C2_N3_OWN_MODELS_PROOF '+canonical+'\n');
if(failed)process.exitCode=1;

